#include <iostream>
#include <cstring>

int main() {
    // 1. memcpy between disjoint buffers
    char src[] = "Copy this string";
    char dst[17];
    std::memcpy(dst, src, sizeof(src));
    std::cout << "dst after memcpy: " << dst << "\n";

    // 2. memset to reset memory
    char buffer[10];
    std::memset(buffer, 'A', 5);
    buffer[5] = '\0';
    std::cout << "buffer after memset: " << buffer << "\n";

    // 3. memmove on overlapping regions
    char overlap_str[] = "Home Sweet Home";
    // Shift 10 characters starting at index 5 ("Sweet Home") to index 0
    std::memmove(overlap_str, &overlap_str[5], 10);
    std::cout << "overlap_str after memmove: " << overlap_str << "\n";
    return 0;
}

#include <iostream>
#include <cstring>

int main() {
    // 1. memmove with overlapping buffer
    char text[32] = "Home Sweet Home";
    std::cout << "Before memmove: " << text << "\n";
    // Shift 10 bytes starting from index 5 to index 0
    std::memmove(text, &text[5], 10);
    std::cout << "After memmove:  " << text << "\n";

    // 2. memcmp comparison
    char s1[] = "ABCDEFG";
    char s2[] = "ABCDXYZ";
    std::cout << "memcmp(s1, s2, 4) = " << std::memcmp(s1, s2, 4) << "\n";
    std::cout << "memcmp(s1, s2, 7) = " << std::memcmp(s1, s2, 7) << "\n";

    // 3. memchr searching
    const char phrase[] = "This is a string";
    const void* found = std::memchr(phrase, 'r', 16);
    if (found != nullptr) {
        std::cout << "Found 'r', remainder: " << static_cast<const char*>(found) << "\n";
    }

    // 4. memset filling
    char buffer[15] = "BBBBBBBBBBBBBB";
    std::memset(buffer, 'b', 7);
    std::cout << "After memset:   " << buffer << "\n";

    return 0;
}

#include <iostream>
#include <cstring>
#include <string_view>

int main() {
    // Inspecting standard error message for ENOENT (typically error code 2)
    int errCode = 2;
    std::cout << "strerror(" << errCode << "): " << std::strerror(errCode) << "\n";

    // Using strlen on C-style strings
    const char* str1 = "abcdefghijklmnopqrstuvwxyz";
    const char* str2 = "four";
    const char* str3 = "Boston";

    std::cout << "strlen(\"" << str1 << "\"): " << std::strlen(str1) << "\n";
    std::cout << "strlen(\"" << str2 << "\"): " << std::strlen(str2) << "\n";
    std::cout << "strlen(\"" << str3 << "\"): " << std::strlen(str3) << "\n";

    // C++17 string_view equivalent
    std::string_view sv = str1;
    std::cout << "string_view length: " << sv.length() << "\n";

    return 0;
}
